window.addEventListener("load",async()=>{const CN_common=(await import("./common.js")).default;const CN_event=(await import("./event.js")).default;const CN_session=(await import("./session.js")).default;window.addEventListener("unhandledrejection",event=>{const params={static:true,title:"Unexpected Error",message:`
        Sorry, but an unexpected error has occurred which may cause the application to behave incorrectly.
      `,type:"danger"};if(CN_common.is_object(event.reason)){if(event.reason.title)params.title=event.reason.title;if(event.reason.message)params.message=event.reason.message;if(event.reason.error_code){params.message+=`<pre class="pt-3">Error Code: ${event.reason.error_code}</pre>`}}const modal=CN_event.modal_message(params);modal.show()});window.addEventListener("popstate",async event=>{try{await CN_session.load_modules();CN_session.render()}catch(error){CN_session.render_error(error)}});CN_session.start()},{once:true});
